use vstd::prelude::*;

verus! {

    /// Logical helper: is this Unicode scalar an ASCII letter?
    spec fn is_ascii_alpha(c: char) -> bool {
        ('a' <= c && c <= 'z') ||
        ('A' <= c && c <= 'Z')
    }

    /// Checks whether `txt` is nonempty, its last character is an ASCII letter,
    /// and that letter is “standalone” (either it's the only character or
    /// the character just before it is a space).
    fn check_if_last_char_is_a_letter(txt: &str) -> bool
        ensures
            // we characterize exactly the return value
            result ==
            (
                // 1) nonempty
                txt.chars().count() >= 1
                &&
                // 2) last character is an ASCII letter
                is_ascii_alpha(*txt.chars().rev().next().unwrap())
                &&
                // 3) either exactly one character, or the one before the last is a space
                (
                    txt.chars().count() == 1
                    ||
                    *txt.chars().rev().nth(1).unwrap() == ' '
                )
            )
    {
        // Compute the number of chars up‐front.
        let cnt = txt.chars().count();

        // 1) Empty?
        if cnt == 0 {
            return false;
        }

        // Peek at the last character.
        let mut rev = txt.chars().rev();
        let last = rev.next().unwrap(); // safe because cnt >= 1

        // 2) Is it ASCII α?
        if ! (('a' <= last && last <= 'z') || ('A' <= last && last <= 'Z')) {
            return false;
        }

        // 3) If there's only one char, we succeed now.
        if cnt == 1 {
            return true;
        }

        // Otherwise we must have a second‐last char and it must be a space.
        let second_last = rev.next().unwrap(); // safe because cnt >= 2
        second_last == ' '
    }

} // end verus!

